const translationCodes = ["vi", "en", "zh-CN", "fr", "es", "pt-BR", "id", "th", "ru", "ar"] as const;
const expandedDictionaries = Object.fromEntries(supportedLocales.map((locale) => {
  const dictionary: Record<string, string> = { ...dictionaries[locale] };
  const source = keyed.vi ?? {};
  for (const [key, viText] of Object.entries(source)) {
    let value = keyed[locale]?.[key];
    if (!value) {
      const row = rows.find((candidate) => candidate[0] === viText);
      if (row) value = row[translationCodes.indexOf(locale)];
    }
    dictionary[key] = value ?? (locale === "vi" ? viText : source[key]!);
  }
  return [locale, dictionary];
})) as Record<Locale, Record<string, string>>;

export const translationDictionaries = expandedDictionaries;

export const i18nStyles = `.locale-picker{display:inline-flex;align-items:center;gap:8px;position:relative;z-index:40}.locale-picker label{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0)}.locale-picker select{max-width:168px;min-height:38px;padding:7px 30px 7px 12px;border:1px solid color-mix(in srgb,currentColor 24%,transparent);border-radius:999px;background:color-mix(in srgb,var(--surface,#fff) 88%,transparent);color:inherit;font:inherit;font-size:13px;cursor:pointer}.top-actions .locale-picker select{max-width:130px}.sidebar>.locale-picker{margin:8px 18px 14px}.sidebar>.locale-picker select{width:100%}.locale-picker--inline{position:relative!important;inset:auto!important;z-index:4!important;background:transparent!important;padding:0!important;flex:0 0 auto;margin-left:auto}.locale-picker--inline select{max-width:132px;background:#07152c;color:#eaf5ff;border-color:#45658f}.aiv3-manifesto .locale-picker--inline{margin:10px 0}.aiv3-sidebar .locale-picker--inline{align-self:stretch;margin:0 8px}.aiv3-sidebar .locale-picker--inline select{width:100%}[dir="rtl"] body{direction:rtl}[dir="rtl"] .ref-page,[dir="rtl"] .ref-auth,[dir="rtl"] .ref-customer,[dir="rtl"] .customer{text-align:right}[dir="rtl"] .sidebar,[dir="rtl"] .ref-customer>aside{order:2}[dir="rtl"] input,[dir="rtl"] textarea{direction:rtl}`;

const safeJson = (value: unknown) => JSON.stringify(value).replaceAll("<", "\\u003c");

export function customerI18nScript() {
  return String.raw`;(()=>{const supported=${safeJson(supportedLocales)},names=${safeJson(localeNames)},dicts=${safeJson(translationDictionaries)};
const normalise=value=>{const raw=String(value||'').trim(),lower=raw.toLowerCase();if(lower==='zh'||lower.startsWith('zh-'))return'zh-CN';if(lower==='pt'||lower.startsWith('pt-'))return'pt-BR';return supported.find(x=>x.toLowerCase()===lower)||supported.find(x=>lower.startsWith(x.toLowerCase()+'-'))||''};
const saved=decodeURIComponent((document.cookie.split('; ').find(v=>v.startsWith('smm_locale='))||'=').split('=').slice(1).join('=')),browser=(navigator.languages||[navigator.language]).map(normalise).find(Boolean),locale=normalise(saved)||browser||'vi';let active=locale;
const source=dicts.vi,t=(key,params={})=>String((dicts[active]&&dicts[active][key])||source[key]||key).replace(/\{([a-zA-Z0-9_]+)\}/g,(_,name)=>String(params[name]??''));
const phrase=key=>{const known=new Set(['⏱','✓','●','＋','↗','▤','◇','◉','◎','⌂']);return key in source?key:key};
const keys={vi:source};for(const locale of supported)keys[locale]=dicts[locale];const exact=new Map();for(const key of Object.keys(source))for(const locale of supported){const val=keys[locale][key];if(val&&!exact.has(val))exact.set(val,key)}
const apply=root=>{if(!(root instanceof Element||root instanceof Document))return;const nodes=[];if(root instanceof Element&&root.matches('[data-i18n],[data-i18n-parts],[data-i18n-placeholder],[data-i18n-aria-label]'))nodes.push(root);nodes.push(...root.querySelectorAll('[data-i18n],[data-i18n-parts],[data-i18n-placeholder],[data-i18n-aria-label]'));nodes.forEach(el=>{if(el.hasAttribute('data-i18n')){const params=el.dataset.i18nParams?JSON.parse(el.dataset.i18nParams):{};el.textContent=t(el.dataset.i18n,params)}if(el.hasAttribute('data-i18n-parts')){const parts=el.dataset.i18nParts.split('|'),children=[...el.childNodes].filter(n=>n.nodeType===Node.TEXT_NODE||n.nodeType===Node.ELEMENT_NODE&&n.tagName==='EM'),ai=parts.length===4&&el.hasAttribute('data-theme-content')&&el.dataset.themeContent==='heroTitle';if(parts.length===children.length||(ai&&el.childNodes.length===6))parts.forEach((key,index)=>{const target=ai?[el.childNodes[0],el.childNodes[2],el.childNodes[4],el.childNodes[5]][index]:children[index];const value=t(key);if(target.nodeType===Node.TEXT_NODE)target.nodeValue=value;else target.textContent=value});if(ai)el.childNodes[4].nodeValue=el.childNodes[4].nodeValue.replace(/\s*$/,' ') }if(el.hasAttribute('data-i18n-placeholder'))el.setAttribute('placeholder',t(el.dataset.i18nPlaceholder));if(el.hasAttribute('data-i18n-aria-label'))el.setAttribute('aria-label',t(el.dataset.i18nAriaLabel))})};
const mountPicker=()=>{const host=document.querySelector('html[data-theme="AI_COSMIC_FUTURE"] .aiv3-nav,html[data-theme="AI_COSMIC_FUTURE"] .aiv3-topbar,html[data-theme="AI_COSMIC_FUTURE"] .aiv3-manifesto,html[data-theme="AI_COSMIC_FUTURE"] .aiv3-sidebar')||document.body,existing=document.querySelector('.locale-picker');if(existing){if(host!==document.body){existing.classList.add('locale-picker--inline');existing.style.cssText='';if(existing.parentElement!==host)host.append(existing)}else if(existing.classList.contains('locale-picker--inline')){existing.classList.remove('locale-picker--inline');existing.style.cssText='position:fixed;top:12px;right:12px;z-index:9999;background:var(--surface,#fff);border-radius:24px;padding:2px 5px';if(existing.parentElement!==document.body)document.body.append(existing)}return}const wrap=document.createElement('div');wrap.className='locale-picker';if(host!==document.body)wrap.classList.add('locale-picker--inline');wrap.innerHTML='<label for="locale-select">Language</label><select id="locale-select" aria-label="Language">'+supported.map(code=>'<option value="'+code+'">'+names[code]+'</option>').join('')+'</select>';if(host===document.body)wrap.style.cssText='position:fixed;top:12px;right:12px;z-index:9999;background:var(--surface,#fff);border-radius:24px;padding:2px 5px';host.append(wrap);const select=wrap.querySelector('select');select.value=active;select.onchange=()=>{active=normalise(select.value)||'vi';document.cookie='smm_locale='+encodeURIComponent(active)+'; Path=/; Max-Age=31536000; SameSite=Lax';sync();select.value=active}};
const sync=()=>{document.documentElement.lang=active;document.documentElement.dir=active==='ar'?'rtl':'ltr';apply(document);const select=document.querySelector('#locale-select');if(select)select.value=active;document.title=document.title.split(' · ').map(part=>t(part)).join(' · ')};window.__i18n={get locale(){return active},t,apply,setLocale(value){active=normalise(value)||'vi';document.cookie='smm_locale='+encodeURIComponent(active)+'; Path=/; Max-Age=31536000; SameSite=Lax';sync()}};sync();let queued=false;new MutationObserver(records=>{if(queued)return;queued=true;queueMicrotask(()=>{queued=false;for(const record of records)for(const node of record.addedNodes){if(node instanceof Element)apply(node)}mountPicker()})}).observe(document.body,{childList:true,subtree:true});mountPicker()})();`;
}
